{
  "name": "be-guild",
  "displayName": "BE guild",
  "version": "0.1.0",
  "description": "Backend knowledge for fcp: cloud, client and SDK module guides, repo conventions, and the BE planner with its explorer and critic agents",
  "author": { "name": "Rhino Health BE guild" },
  "repository": "https://github.com/RhinoHealth/claude-plugins",
  "keywords": ["fcp", "django", "grpc", "backend"],
  "experimental": { "evals": "evals" }
}

# RhinoHealth/claude-plugins/catalog.yaml — every shared skill, its plugin and its owner.
# Owners keep their skill's evals green and run its monthly rule diet. CI checks this file against plugins/*/skills.
owners:
  platform: { slack: "<agents channel ID>" } # no Platform team on GitHub yet (Sean and Shai)
  shai: { github: "<Shai's GitHub login>" }
  fe-guild: { github: "@RhinoHealth/frontend-guild" }
  be-guild: { github: "@RhinoHealth/backend-guild" }
  devops: { github: "@RhinoHealth/devops" }
  security: { slack: "<Ronen's Slack ID>" }
skills:
  plan-and-grill: { plugin: rhino-core, owner: platform }
  verify: { plugin: rhino-core, owner: [platform, shai] }
  pr-story: { plugin: rhino-core, owner: [platform, shai] }
  fix-bug: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  fix-ci: { plugin: rhino-core, owner: platform }
  upgrade-dependency: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  remove-dead-code: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  add-tests: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  merge-duplicates: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  small-feature: { plugin: rhino-core, owner: [fe-guild, be-guild] }
  fe-codebase: { plugin: fe-guild, owner: fe-guild }
  be-codebase: { plugin: be-guild, owner: be-guild }
  fix-flaky-test: { plugin: be-guild, owner: be-guild }
  devops-codebase: { plugin: devops-guild, owner: devops }
  infra-change: { plugin: devops-guild, owner: devops }
  security-fix: { plugin: devops-guild, owner: [devops, security] }
  fcp-lab: { plugin: fcp-lab, owner: be-guild } # lives in RhinoHealth/fcp-local-lab
  kb: { plugin: kb, owner: shai } # lives in RhinoHealth/rnd-kb-tooling

{
  "description": "rhino-core: refuse writing secrets or editing credential files; lint each edited file",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit|MultiEdit",
        "hooks": [
          { "type": "command", "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/hooks/guard_write.py\"", "timeout": 5 }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write|Edit|MultiEdit",
        "hooks": [
          { "type": "command", "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/hooks/lint_after_edit.py\"", "timeout": 60 }
        ]
      }
    ]
  }
}

// Managed settings for every engineer: G0 + G1 + G8 keys in one policy, Platform is the single writer.
// Delivery (claude.ai admin console or Fleet MDM) is decided with DevOps and Ronen (Security).
{
  "strictKnownMarketplaces": [
    { "source": "github", "repo": "RhinoHealth/*" },                     // our marketplaces, any ref or path
    { "source": "github", "repo": "anthropics/claude-plugins-official" }, // decide with Ronen: figma, frontend-design come from here
    { "source": "skills-dir" }                                            // keeps people's own ~/.claude/skills loading
  ],
  "extraKnownMarketplaces": {
    "rhino": {                                                            // the pilot profile swaps in "rhino-latest" (ref main)
      "source": { "source": "github", "repo": "RhinoHealth/claude-plugins", "ref": "stable" },
      "autoUpdate": true
    }
  },
  "enabledPlugins": { "rhino-core@rhino": true },                         // guild plugins are enabled per repo (fcp/.claude/settings.json)
  "allowManagedMcpServersOnly": true,
  "allowedMcpServers": [
    { "serverUrl": "https://mcp-dev3.example.com/*" },                // Rhino MCP on test data; prod reaches customer data
    { "serverUrl": "https://<compliance connector host>/*" },             // from G6-13 (Nave)
    { "serverUrl": "https://<each connector in the inventory>/*" }        // Jira, Slack, Figma: don't cut what people use
  ],
  "deniedModels": ["fable"],                                              // G0: Fable needs 30-day retention (a compliance call)
  "env": {                                                                // G1 owns this block
    "CLAUDE_CODE_ENABLE_TELEMETRY": "1",
    "OTEL_EXPORTER_OTLP_ENDPOINT": "https://<otel collector on inf>",
    "OTEL_LOG_USER_PROMPTS": "0",
    "OTEL_LOG_TOOL_DETAILS": "0"
  }
}
